B.aOg=s(["\ud655\uc778\ud588\uc5b4.","\uadf8\ub798, \uc54c\uaca0\uc5b4.","\ub124 \ub9d0\uc740 \uc774\ud574\ud588\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uc5c8\uc5b4.","\uc911\uc694\ud55c \uc598\uae30\uc778 \uac74 \uc54c\uaca0\uc5b4.","\ub124 \ub9d0\uc774\uba74 \uac00\ubccd\uac8c \ub118\uae30\uc9c4 \uc54a\uc544."],t.s)
B.aET=s(["\uc544\uc9c1 \uc624\ub298 \uacc4\uc0b0 \uc548 \ub05d\ub0ac\uc5b4. \ub05d\ub098\uace0 \ubcf4\uc790.","\uc624\ub298 \uc7a5 \uc26c\uc796\uc544. \uc9c0\ub09c \uae30\ub85d\uc774\ub098 \ubcf4\uc790.","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\ub124. \uad1c\ud788 \uc758\ubbf8 \ubd99\uc774\uc9c0 \ub9d0\uc790.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc804\uccb4\ub3c4 \ud50c\ub7ec\uc2a4\ub124. \uc218\uc218\ub8cc \ube80 \uac83\ub3c4 \ub9de\uc9c0?","\uc624\ub298\uc740 \ubc8c\uc5c8\ub124. \uadf8\ub798\ub3c4 \uc544\uc9c1 \uc804\uccb4\ub294 \ub9c8\uc774\ub108\uc2a4\uc57c.","\uc624\ub298 \uc880 \uc783\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4. \uc5b4\ub514\uae4c\uc9c0 \ubc84\ud2f8\uc9c0\ub9cc \uc815\ud574.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc804\uccb4\ub3c4 \ub9c8\uc774\ub108\uc2a4\uc57c. \uc77c\ub2e8 \ub3c8\ubd80\ud130 \uc9c0\ucf1c."],t.s)
B.aFs=s(["\uc783\uc740 \ub3c8\ubd80\ud130 \uc815\ud655\ud788 \uc801\uc5b4. \uadf8\ub798\uc57c \ub2e4\uc74c \uacc4\uc0b0\uc774 \ub3fc.","\uc774\ubc88 \uc190\ud574\ub791 \ub124\uac00 \uc798\ubabb \ubcf8 \uac74 \ub530\ub85c \ubcf4\uc790."],t.s)
B.aEk=s(["\ubc88 \uac74 \uc88b\uc9c0. \uc218\uc218\ub8cc \ube7c\uace0\ub3c4 \ub0a8\uc558\ub294\uc9c0\ub9cc \ubd10.","\uc774\ubc88\uc5d0 \uc65c \ubc8c\uc5c8\ub294\uc9c0 \uc801\uc5b4 \ub46c. \uc6b4\uc778\uc9c0 \uc544\ub2cc\uc9c0\ub294 \ub2e4\uc74c\uc5d0 \ubcf4\uc790."],t.s)
B.aRR=s(["\ub0a8 \ub9d0\ub9cc \ub4e3\uace0 \uc0ac\uc9c0\ub294 \ub9c8. \ub124\uac00 \uac10\ub2f9\ud560 \ub3c8\ubd80\ud130 \uc815\ud574.","\uc0ac\uae30 \uc804\uc5d0 \uc5bc\ub9c8\uae4c\uc9c0 \uc783\uc744 \uc218 \uc788\ub294\uc9c0 \uba3c\uc800 \uc815\ud574."],t.s)
B.aH7=s(["\ucc98\uc74c \uacc4\uc0b0\uc774\ub791 \uc9c0\uae08 \uc22b\uc790\ubd80\ud130 \ub9de\ucdb0 \ubcf4\uc790.","\uc5b4\ub514\uc11c \uacc4\uc0b0\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ud55c \uc904\uc529 \ubcf4\uc790."],t.s)
