B.aG1=s(["\ub2e4\uc74c \uacc4\uc0b0\uc5d0\uc11c \uac19\uc740 \uc2e4\uc218\ub9cc \uc548 \ud558\uba74 \ub3fc.","\ub3c4\uc6c0 \ub410\uc73c\uba74 \ub410\uc5b4.","\ubb50\uac00 \ubd88\uc548\ud55c\uc9c0 \ud558\ub098\uc529 \ub9d0\ud574 \ubd10.","\uc88b\uc544. \uc77c\uc815\ubd80\ud130 \ub9de\ucdb0 \ubcf4\uc790."],t.s)
B.aMD=s(["\uc815\ud655\ud788 \uc5bc\ub9c8\uc57c?","\ucc98\uc74c \uc0b0 \uac00\uaca9\uc740 \uc5bc\ub9c8\uc600\uc5b4?","\uadf8\ub798\uc11c \ub2e4\uc74c\uc5d0\ub294 \ubb50 \ud560 \uac74\ub370?"],t.s)
