B.bJc=new A.me(B.aND,B.aQ5,B.aFF,B.aHk,B.aH6,B.aFy,"\uac19\uc740 \ub9d0 \ud574\ub3c4 \uc22b\uc790\ub294 \uc548 \ubc14\ub00c\uc5b4. \ub2e4\ub978 \uadfc\uac70 \uc788\uc5b4?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \ubb34\uc2a8 \uc218\uc775\uc778\uc9c0 \ud655\uc778\ud560 \uac78 \ubcf4\uc5ec \uc918.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \uc190\uc2e4\uc774\uba74 \uc5b4\ub514\uc11c \ub09c \uac74\uc9c0 \ubcf4\uc5ec \uc918.","\uc624\ub298\uc740 \uc190\ud574\uc57c. \ubc88 \uac74 \ub2e4\ub978 \ub0a0 \uc598\uae30\uc57c?","\uc624\ub298\uc740 \ubc8c\uc5c8\uc5b4. \uc804\uccb4 \uc190\uc2e4\uc744 \ub9d0\ud55c \uac70\uba74 \uadf8\ub807\uac8c \ub9d0\ud574.")
B.aRB=s(["\uc751, \uc77d\uc5c8\uc5b4.","\ub124 \ub9d0\uc758 \ub290\ub08c\uc740 \uc54c\uaca0\uc5b4.","\uc194\uc9c1\ud558\uac8c \ub9d0\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\ucc9c\ucc9c\ud788 \uc77d\uc5b4 \ubd24\uc5b4.","\uadf8 \ub9c8\uc74c\uc744 \uac00\ubccd\uac8c \ub118\uae30\uace0 \uc2f6\uc9c0 \uc54a\uc544.","\ub124\uac00 \ub290\ub080 \uacb0\uc744 \uc774\uc81c\ub294 \uc54c\uc544."],t.s)
B.aFQ=s(["\uc544\uc9c1 \uacb0\uacfc\ub3c4 \uc548 \ub098\uc654\ub294\ub370 \ub9c8\uc74c\ubd80\ud130 \ub2ec\ub9ac\uc9c4 \ub9d0\uc790.","\uc624\ub298\uc740 \uc7a5 \uc26c\uc796\uc544. \uc22b\uc790\ub3c4 \uc7a0\uae50 \ub0b4\ub824\ub193\uc790.","\uc624\ub298\uc740 \uc870\uc6a9\ud588\ub124. \uc774\ub7f0 \ub0a0\ub3c4 \uc788\ub294 \uac70\uc9c0.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub124. \uc798\ub410\ub2e4.","\uc624\ub298\uc740 \uc62c\ub790\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \uadf8\ub798\ub3c4 \uc870\uae08 \ub098\uc544\uc84c\ub124.","\uc624\ub298\uc740 \ub0b4\ub824\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \uac74 \ub0a8\uc544 \uc788\ub124.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \ud63c\uc790 \ubc84\ud2f0\uc9c4 \ub9c8."],t.s)
B.aRP=s(["\ub124\uac00 \uc88b\uc544\ud55c \uac70\ub791 \uc0ac\ub78c\ub4e4\uc774 \uacc4\uc18d \uc0ac\ub294 \uac74 \ub2e4\ub97c \uc218 \uc788\uc5b4.","\uc18d\uc0c1\ud558\uaca0\uc9c0\ub9cc, \uc4f0\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc9c4\uc9dc \ud3b8\ud588\ub294\uc9c0 \ub2e4\uc2dc \ubcf4\uc790."],t.s)
B.aJy=s(["\uc798\ub410\ub2e4. \uadf8\ub798\ub3c4 \ub124 \ucde8\ud5a5\ub9cc \ub9de\uc740 \uac74 \uc544\ub2cc\uc9c0 \ud55c \ubc88 \ubcfc\ub798?","\ubc88 \uac74 \uae30\uc05c\ub370, \uc0ac\ub78c\ub4e4\uc774 \uacc4\uc18d \uc4f0\uace0 \uc2f6\uc5b4 \ud558\ub294\uc9c0\ub3c4 \uad81\uae08\ud574."],t.s)
B.aIq=s(["\ub124\uac00 \uc9c1\uc811 \uc368 \ubcf4\uace0 \uc88b\uc740\uc9c0\ubd80\ud130 \ubd10. \ub0a8\ub4e4\uc774 \uc608\uc058\ub2e4\uace0 \ud558\ub294 \uac74 \ub098\uc911\uc774\uace0.","\ud55c \ubc88 \uc0ac\uace0 \ub9c8\ub294 \ubb3c\uac74\uc778\uc9c0 \uc790\uafb8 \ucc3e\ub294 \ubb3c\uac74\uc778\uc9c0 \ubcf4\uba74 \uc5b4\ub54c?"],t.s)
B.aRE=s(["\uadf8\ub54c \ub9c8\uc74c\uc5d0 \ub4e4\uc5c8\ub358 \uc774\uc720\ub791 \ub3c8\uc774 \ub420 \uac70\ub77c \ubcf8 \uc774\uc720\ub294 \uac19\uc558\uc5b4?","\uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c \uc4f0\ub294 \ubaa8\uc2b5\uae4c\uc9c0 \ubd24\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790."],t.s)
B.aHt=s([B.aRP,B.aJy,B.aIq,B.aRE],t.rj)
B.aMK=s(["\ubbf8\uc548\ud558\ub2e4\uace0 \ub9d0\ud574 \uc900 \ub9c8\uc74c\uc740 \uc54c\uaca0\uc5b4.","\ub0b4\uac00 \ud55c \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub410\ub2e4\ub2c8 \ub2e4\ud589\uc774\uc57c.","\uc9c0\uae08 \ub290\ub07c\ub294 \uac78 \uc5b5\uc9c0\ub85c \uc228\uae30\uc9c0 \uc54a\uc544\ub3c4 \ub3fc.","\uc6b0\ub9ac \ub458 \ub2e4 \ud3b8\ud55c \uacc4\ud68d\uc774\uba74 \uc88b\uaca0\uc5b4."],t.s)
B.aGE=s(["\uadf8 \ud68c\uc0ac \ubb3c\uac74, \uc368 \ubcf8 \uc0ac\ub78c\uc740 \ubb50\ub798?","\ub108\ub294 \uadf8 \ubb3c\uac74 \ub9c8\uc74c\uc5d0 \ub4e4\uc5c8\uc5b4?","\uc624\ub298\uc740 \uc5bc\ub9c8\uae4c\uc9c0 \uad1c\ucc2e\uc544?"],t.s)
B.aMF=s(["\uc804\uc5d0 \u201c{memory}\u201d\ub77c\uace0 \ub9d0\ud588\ub358 \uac70 \uae30\uc5b5\ub098.","\ub0b4\uac00 \uae30\uc5b5\ud558\ub294 \ub124 \ub9d0\uc740 \u201c{memory}\u201d\uc57c.","\uc9c0\ub09c\ubc88\uc5d0\ub294 \u201c{memory}\u201d\ub77c\uace0 \ud588\uc5c8\uc9c0."],t.s)
B.bJ9=new A.me(B.aRB,B.aFQ,B.aHt,B.aMK,B.aGE,B.aMF,"\uac19\uc740 \uc598\uae30\uac00 \uc790\uafb8 \ub3cc\uc544\uc624\ub124. \ub124 \ub9c8\uc74c\uc740 \uadf8\ub300\ub85c\uc57c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \ubcf8\uc804 \uc544\ub798\uc57c. \ub124\uac00 \ub9d0\ud55c \uc218\uc775\uc740 \uc5b4\ub514\uc5d0\uc11c \ub09c \uac78\uae4c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub9c8\uc74c\uc5d0 \uac78\ub9b0 \ub2e4\ub978 \uc190\uc2e4\uc774 \uc788\uc5b4?","\uc624\ub298\uc740 \ub0b4\ub824\uac14\uc5b4. \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc744 \ub9d0\ud55c \uac78\uae4c?","\uc624\ub298\uc740 \uc62c\ub790\uc5b4. \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c\ub294 \ub73b\uc774\uc57c?")
B.aFx=s(["\ud655\uc778\ud588\uc5b4.","\uc88b\uc544, \uc774\ud574\ud588\uc5b4.","\ub124 \uc758\uacac\ub3c4 \uc54c\uaca0\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uace0 \uc815\ub9ac\ud588\uc5b4.","\uc911\uc694\ud55c \uc598\uae30\uc778 \uac74 \uc54c\uaca0\uc5b4.","\ub124\uac00 \ub9d0\ud55c \uac70\uba74 \uc77c\ub2e8 \ubbff\uc744\uac8c."],t.s)
B.aO5=s(["\uc544\uc9c1 \ub9c8\uac10 \uc804\uc774\uc57c. \uacb0\uacfc \ub098\uc628 \ub2e4\uc74c\uc5d0 \uc598\uae30\ud558\uc790.","\uc624\ub298 \uc7a5 \uc26c\uc796\uc544. \ub2e4\uc74c \uc8fc \uacc4\ud68d\uc774\ub098 \uc815\ud558\uc790.","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\ub124. \uacc4\ud68d\uc5d0\uc11c \ubc97\uc5b4\ub09c \uac83\ub9cc \ubd10.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\uc57c. \uc695\uc2ec\ub0bc \uc120\ubd80\ud130 \uc815\ud574.","\uc624\ub298\uc740 \ubc8c\uc5c8\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c.","\uc624\ub298\uc740 \uc783\uc5c8\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4. \uadf8\ub9cc\ub458 \uc120 \ub2e4\uc2dc \ubd10.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \uc5bc\ub9c8\uae4c\uc9c0 \uc904\uc77c\uc9c0 \ubc14\ub85c \uc815\ud574."],t.s)
B.aIS=s(["\uc190\ud574 \ubd24\uc73c\uba74 \ub2e4\uc74c\uc5d4 \uc5bc\ub9c8\ub9cc \uc0b4\uc9c0 \uc9c0\uae08 \uc815\ud574.","\ud2c0\ub9b0 \uac74 \ubc14\ub85c \uace0\uce58\uba74 \ub3fc. \ub0b4\uc77c \ud560 \uc77c\ubd80\ud130 \ud558\ub098 \uc815\ud558\uc790."],t.s)
B.aIZ=s(["\ubc8c\uc5c8\uc73c\uba74 \ub410\uc5b4. \uc774\uc81c \uc5b4\ub514\uc11c \uba48\ucd9c\uc9c0\ub9cc \uc815\ud574.","\uc798\ub410\ub124. \ub2e4\uc74c\uc5d0\ub3c4 \ubcfc \uc22b\uc790\ub791 \ub0a0\uc9dc\ub97c \ubc14\ub85c \uc801\uc790."],t.s)
B.aG_=s(["\ubb58 \uc0b4\uc9c0\ubcf4\ub2e4 \uc5b8\uc81c \uc0ac\uace0 \uc5b8\uc81c \uadf8\ub9cc\ub458\uc9c0\ubd80\ud130 \uc815\ud574.","\ub9d0\ub9cc \uc88b\uc740 \ud68c\uc0ac \ub9d0\uace0 \uc57d\uc18d\ud55c \uac78 \uc81c\ub54c \ud588\ub294\uc9c0 \ubd10."],t.s)
B.aRk=s(["\ucc98\uc74c \uacc4\ud68d\uc5d0\uc11c \ubb50\uac00 \ub2ec\ub77c\uc84c\ub294\uc9c0 \ubc14\ub85c \ucc3e\uc544.","\uc798\ud55c \uac70 \ud558\ub098, \ud2c0\ub9b0 \uac70 \ud558\ub098\ub9cc \uc801\uace0 \ub2e4\uc74c \ud589\ub3d9 \uc815\ud558\uc790."],t.s)
B.aIN=s([B.aIS,B.aIZ,B.aG_,B.aRk],t.rj)
B.aRK=s(["\uc0ac\uacfc\ub294 \ubc1b\uc558\uc5b4.","\ub3c4\uc6c0\uc774 \ub410\ub2e4\uba74 \ub410\uc5b4.","\ubb50\uac00 \uc81c\uc77c \ubd88\uc548\ud574? \ub0b4\uac00 \ud560 \uc218 \uc788\ub294 \uac74 \ub9e1\uc744\uac8c.","\uc88b\uc544. \uba87 \uc2dc\uc5d0 \ud560\uc9c0\ub9cc \uc815\ud558\uc790."],t.s)
B.aIT=s(["\uadf8\ub798\uc11c \ub0b4\uc77c \uba87 \uc2dc\uc5d0 \ubb58 \ubcfc \uac74\ub370?","\ubaa9\ud45c \uc22b\uc790 \ud558\ub098\ub9cc \uc815\ud574.","\uc5b8\uc81c \ub2e4\uc2dc \ud655\uc778\ud560\uc9c0\ub3c4 \uc815\ud558\uc790."],t.s)
B.aLT=s(["\uc804\uc5d0 \ub124\uac00 \u201c{memory}\u201d\ub77c\uace0 \ud588\uc796\uc544.","\uc804\uc5d0 \ub9d0\ud55c \uac74 \u201c{memory}\u201d\uc600\uc9c0.","\ub0b4\uac00 \uc801\uc5b4 \ub454 \uac74 \u201c{memory}\u201d\uc57c."],t.s)
B.bJ8=new A.me(B.aFx,B.aO5,B.aIN,B.aRK,B.aIT,B.aLT,"\uac19\uc740 \uc598\uae30\ub9cc \ud574\uc11c\ub294 \uc548 \ubc14\ub00c\uc5b4. \ub2ec\ub77c\uc9c4 \uac8c \ubb50\uc57c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \uc5b4\ub514\uc11c \uc218\uc775\uc774\ub77c\uace0 \ubcf8 \uac74\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud574.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \ub370\uc11c \uc783\uc740 \uac70\ub77c\uba74 \uadf8\uac78 \ub530\ub85c \ub9d0\ud574.","\uc624\ub298\uc740 \uc190\ud574\uc57c. \uc624\ub298 \ubc88 \ub3c8\uc744 \ub9d0\ud55c \uac70\uba74 \uc22b\uc790 \ub2e4\uc2dc \ubd10.","\uc624\ub298\uc740 \uc218\uc775\uc774\uc57c. \uc804\uccb4 \uc190\uc2e4\uc774\ub791 \ub098\ub220\uc11c \ub9d0\ud574.")
B.aLk=s(["\uc751, \uc77d\uc5c8\uc5b4.","\ubb34\uc2a8 \ub9d0\uc778\uc9c0 \uc54c\uaca0\uc5b4.","\ub05d\uae4c\uc9c0 \ub4e4\uc5b4 \ubcfc\uac8c.","\ub098\ud55c\ud14c\ub294 \ud3b8\ud558\uac8c \ub9d0\ud574\ub3c4 \ub3fc.","\ub124\uac00 \uba3c\uc800 \ub9d0\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\ub124 \uc598\uae30\ub77c\uba74 \uc5b8\uc81c\ub4e0 \ub4e4\uc5b4 \uc904\uac8c."],t.s)
B.aNE=s(["\uc544\uc9c1 \uacb0\uacfc\ub3c4 \uc548 \ub098\uc654\uc796\uc544. \ubbf8\ub9ac \ub124 \ud0d3\ubd80\ud130 \ud558\uc9c0 \ub9c8.","\uc624\ub298\uc740 \uc7a5\ub3c4 \uc26c\ub294\ub370 \uc6b0\ub9ac\ub3c4 \uc880 \uc26c\uc790.","\uc624\ub298\uc740 \uadf8\ub300\ub85c\ub124. \ubb34\ub9ac \uc548 \ud55c \uac83\ub3c4 \uc798\ud55c \uac70\uc57c.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub77c \uae30\uc058\uaca0\ub2e4. \uadf8\ub798\ub3c4 \ubb34\ub9ac\ud558\uc9c4 \ub9c8.","\uc624\ub298 \ubc88 \uac74 \uc798\ub410\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \uc870\uae09\ud574\ud558\uc9c0 \ub9c8.","\uc624\ub298 \uc783\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c \uc18d\uc0c1\ud558\uaca0\ub2e4. \uc7a0\uae50 \uc26c\uc790."],t.s)
B.aS6=s(["\uc18d\uc0c1\ud55c \uac74 \uc54c\uaca0\uc5b4. \uc9c0\uae08 \uac19\uc774 \ubcfc\uae4c, \uc7a0\uae50 \uc26c\uace0 \ubcfc\uae4c?","\uc783\uc5c8\ub2e4\uace0 \ud63c\uc790 \uc815\ub9ac\ud558\uc9c0 \ub9c8. \ub124\uac00 \uc6d0\ud558\ub294 \ub3c4\uc6c0\ubd80\ud130 \ub9d0\ud574 \uc918."],t.s)
B.aRx=s(["\uae30\uc058\uaca0\ub2e4. \uadf8\ub798\ub3c4 \uadf8 \ud68c\uc0ac \uc0ac\ub78c\ub4e4\ub3c4 \uc624\ub798 \ubc84\ud2f0\ub294\uc9c0\ub294 \ubcf4\uc790.","\uc798\ub410\ub124. \ub108\ub3c4 \ubb34\ub9ac\ud55c \uac74 \uc5c6\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud574."],t.s)
B.aOP=s(["\ub300\ud45c\uac00 \uc88b\uc740 \ub9d0 \ud558\ub294 \uac83\ubcf4\ub2e4 \uc0ac\ub78c\ub4e4\uc774 \uacc4\uc18d \ub0a8\ub294 \ud68c\uc0ac\uc778\uc9c0 \ubd10.","\uace0\uac1d\uc774 \ubb38\uc81c \uc0dd\uacbc\uc744 \ub54c \uc5b4\ub5bb\uac8c \ub300\ud574 \uc8fc\ub294\uc9c0\ub3c4 \ubcf4\uba74 \uc88b\uaca0\uc5b4."],t.s)
B.aG7=s(["\uc22b\uc790 \ub9d0\uace0 \uadf8 \ud68c\uc0ac \ub54c\ubb38\uc5d0 \ud798\ub4e4\uc5b4\uc9c4 \uc0ac\ub78c\uc740 \uc5c6\uc5c8\ub294\uc9c0\ub3c4 \ubcf4\uc790.","\uadf8\ub54c \ub124\uac00 \ub204\uad6c \ub9d0\uc744 \ubbff\uc5c8\ub294\uc9c0\ub3c4 \uac19\uc774 \ub5a0\uc62c\ub824 \ubcf4\uc790."],t.s)
B.aFe=s([B.aS6,B.aRx,B.aOP,B.aG7],t.rj)
B.aPj=s(["\uc0ac\uacfc\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\ub3c4\uc6c0\uc774 \ub410\ub2e4\ub2c8 \ub098\ub3c4 \uae30\ubed0.","\uc624\ub298\uc740 \uad1c\ucc2e\uc740 \ucc99 \uc548 \ud574\ub3c4 \ub3fc. \uadf8\ub0e5 \ub4e4\uc5b4 \uc904\uae4c?","\ucc9c\ucc9c\ud788 \uac19\uc774 \uc815\ud574 \ubcf4\uc790."],t.s)
B.aGw=s(["\uc9c0\uae08 \ub0b4\uac00 \uc5b4\ub5bb\uac8c \ub3c4\uc640\uc8fc\uba74 \uc88b\uaca0\uc5b4?","\uc624\ub298\uc740 \uc7a0\uae50 \uac19\uc774 \uac78\uc744\uae4c?","\ud63c\uc790 \uacb0\uc815\ud558\uc9c0 \ub9d0\uace0 \ud55c \ubc88 \ub354 \ub9d0\ud574 \uc918."],t.s)
B.aRT=s(["\uc804\uc5d0 \u201c{memory}\u201d\ub77c\uace0 \ub9d0\ud588\ub358 \uac70 \uae30\uc5b5\ud574.","\ub098\ub294 \ub124\uac00 \u201c{memory}\u201d\ub77c\uace0 \ud55c \uac78 \uae30\uc5b5\ud558\uace0 \uc788\uc5b4.","\uc9c0\ub09c\ubc88\uc5d0\ub294 \u201c{memory}\u201d\ub77c\uace0 \ub9d0\ud588\uc5c8\uc9c0."],t.s)
B.bJb=new A.me(B.aLk,B.aNE,B.aFe,B.aPj,B.aGw,B.aRT,"\uac19\uc740 \uac71\uc815\uc774 \uacc4\uc18d \ub3cc\uc544\uc624\ub124. \ub2f5\ubcf4\ub2e4 \uba3c\uc800 \ub124 \uc0c1\ud0dc\ub97c \ubcf4\uc790.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \ub2e4\ub978 \ub370\uc11c \ubc88 \ub3c8\uc744 \ub9d0\ud558\ub294 \uac78\uae4c?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \uadf8\ub798\ub3c4 \uc783\uc5c8\ub2e4\uace0 \ub290\ub080 \uc774\uc720\uac00 \uc788\uc5b4?","\uc624\ub298\uc740 \uc190\ud574\ub85c \ub098\uc640. \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8 \uc598\uae30\uc77c\uae4c?","\uc624\ub298\uc740 \ubc8c\uc5c8\uc5b4. \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c \uc18d\uc0c1\ud558\ub2e4\ub294 \ub73b\uc774\uc57c?")
B.aIy=s(["\uc5b4, \uc77d\uc5c8\uc5b4!","\uc88b\uc544, \ubb34\uc2a8 \ub9d0\uc778\uc9c0 \uc54c\uaca0\uc5b4.","\uc7a0\uae50, \uc774\uac74 \uc880 \ub354 \ub4e4\uc5b4 \ubcf4\uace0 \uc2f6\uc5b4.","\ub124 \uc598\uae30\ub77c\uba74 \ub05d\uae4c\uc9c0 \ub4e3\uc9c0!","\ub098\ud55c\ud14c \uba3c\uc800 \ub9d0\ud55c \uac70\uc9c0?","\ub108\ud55c\ud14c \uc628 \ud1a1\uc774\uba74 \ubc14\ub85c \ubcf4\uac8c \ub3fc."],t.s)
B.aGz=s(["\uc544\uc9c1 \uacb0\uacfc\ub3c4 \uc548 \ub098\uc654\ub294\ub370 \ubc8c\uc368 \uacb0\ub860 \ub0b4\ub9ac\uba74 \uc7ac\ubbf8\uc5c6\uc9c0!","\ud734\uc7a5\uc77c\uc774\uba74 \ubc16\uc5d0 \ub098\uac00\uc11c \uc544\uc774\ub514\uc5b4 \ucc3e\uc790.","\uc624\ub298\uc740 \uc870\uc6a9\ud588\ub124. \ub0b4\uc77c \ud288 \uc218\ub3c4 \uc788\uc796\uc544.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\uc57c! \uadf8\ub798\ub3c4 \ub2e4 \uac78\uc9c0\ub294 \ub9c8.","\uc624\ub298 \ubc8c\uae34 \ud588\ub294\ub370 \uc804\uccb4\ub294 \uc544\uc9c1 \ub9c8\uc774\ub108\uc2a4\ub124. \ubc18\ub4f1 \uccab \uc7a5\uba74\uc778\uac00?","\uc624\ub298\uc740 \ube60\uc84c\uc5b4\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \uac74 \ub0a8\uc558\ub124. \uadf8\ub2e4\uc74c\uc740?","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \ubb34\uc791\uc815 \ub354 \uc138\uac8c \uac00\uba74 \uc548 \ub3fc."],t.s)
B.aKu=s(["\uc18d\uc0c1\ud558\uc9c0. \uadfc\ub370 \uc65c \uc0ac\ub78c\ub4e4\uc774 \uac11\uc790\uae30 \uc548 \uc0ac\uae30 \uc2dc\uc791\ud588\ub294\uc9c0 \uad81\uae08\ud558\uc9c0 \uc54a\uc544?","\uc774\ubc88\uc5d4 \ud2c0\ub838\ub124. \uadf8\ub7fc \uc644\uc804 \ub2e4\ub978 \uc774\uc720\uac00 \uc788\uc5c8\ub358 \uac78\uae4c?"],t.s)
B.aP5=s(["\uc624, \ubc8c\uc5c8\ub124! \uadfc\ub370 \uc0ac\ub78c\ub4e4\uc774 \uc9c4\uc9dc \ub2e4\uc2dc \uc0ac\ub294\uc9c0\ub3c4 \ubd24\uc5b4?","\uc798\ub410\ub2e4! \uc7a0\uae50, \uc6b0\ub9ac \ub610 \uc2e0\ub098\uc11c \uc55e\uc11c\uac00\ub294 \uac74 \uc544\ub2c8\uc9c0?"],t.s)
B.aM9=s(["\uc0ac\ub78c\ub4e4\uc774 \uc694\uc998 \ubb58 \uc790\uafb8 \uc598\uae30\ud558\ub294\uc9c0\ubd80\ud130 \ucc3e\uc544\ubcf4\uc790!","\uc9c1\uc811 \uc368 \ubcf8 \uc0ac\ub78c \ub9cc\ub098\uc11c \ubb3c\uc5b4\ubcf4\uba74 \uc5b4\ub54c?"],t.s)
B.aLa=s(["\ucc98\uc74c\uc5d0 \ubb50\uac00 \uc7ac\ubc0c\uc5b4 \ubcf4\uc5ec\uc11c \uc0c0\ub294\uc9c0 \ub2e4\uc2dc \uc0dd\uac01\ud574 \ubcf4\uc790.","\uc0ac\ub78c\ub4e4 \ubc18\uc751\uc774 \ubc14\ub010 \uc21c\uac04\uc774 \uc788\uc5c8\ub294\uc9c0 \ub5a0\uc62c\ub824 \ubd10!"],t.s)
B.aDN=s([B.aKu,B.aP5,B.aM9,B.aLa],t.rj)
B.aR_=s(["\ubbf8\uc548\ud558\ub2e4\uace0 \ud588\uc73c\ub2c8\uae4c \uc774\ubc88\uc5d4 \ubbff\uc5b4 \ubcfc\uac8c!","\ub098\ub3c4 \uac19\uc774\ud574\uc11c \uc88b\uc558\uc5b4!","\ud63c\uc790 \ub059\ub059\ub300\uc9c0 \ub9d0\uace0 \ub2e4 \ub9d0\ud574 \ubd10.","\uc88b\uc544! \uc7ac\ubbf8\uc788\ub294 \ucabd\uc73c\ub85c \uac00 \ubcf4\uc790."],t.s)
B.aJx=s(["\uadf8\ub2e4\uc74c\uc5d4 \ubb58 \uc2dc\ud5d8\ud574 \ubcfc\uae4c?","\uc8fc\ub9d0\uc5d0 \uac19\uc774 \ud655\uc778\ud558\ub7ec \uac08\ub798?","\uadfc\ub370 \uc2e4\uc81c\ub85c \ub2e4\uc2dc \uc0ac\ub294 \uc0ac\ub78c\ub3c4 \ub298\uc5c8\ub300?"],t.s)
B.aQA=s(["\uc804\uc5d0 \ub124\uac00 \u201c{memory}\u201d\ub77c\uace0 \uba3c\uc800 \ub9d0\ud588\uc796\uc544.","\ub098\ub3c4 \ub124\uac00 \u201c{memory}\u201d\ub77c\uace0 \ud588\ub358 \uac70 \uae30\uc5b5\ub098!","\uc9c0\ub09c\ubc88 \uc6b0\ub9ac \uc598\uae30\ub294 \u201c{memory}\u201d\uc5d0\uc11c \uc2dc\uc791\ud588\uc9c0."],t.s)
B.bJ6=new A.me(B.aIy,B.aGz,B.aDN,B.aR_,B.aJx,B.aQA,"\ub610 \uac19\uc740 \uc8fc\uc81c\uc57c? \uc774\ubc88\uc5d4 \uc644\uc804\ud788 \ub2e4\ub978 \uac00\uc124\ub85c \uac00 \ubcf4\uc790!","\uc7a0\uae50, \uc9c0\uae08\uae4c\uc9c0\ub294 \ub9c8\uc774\ub108\uc2a4\uc778\ub370 \uc218\uc775\uc774\ub77c\uace0? \uc5b4\ub290 \uc22b\uc790 \ubcf8 \uac70\uc57c?","\uc7a0\uae50, \uc9c0\uae08\uae4c\uc9c0\ub294 \ud50c\ub7ec\uc2a4\uc778\ub370 \uc190\uc2e4\uc774\ub77c\uace0? \ub2e4\ub978 \ub370\uc11c \uc783\uc5c8\uc5b4?","\uc7a0\uae50, \uc624\ub298\uc740 \uc190\ud574\uc778\ub370? \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8 \ub9d0\ud55c \uac70\uc57c?","\uc7a0\uae50, \uc624\ub298\uc740 \ubc8c\uc5c8\ub294\ub370? \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub77c\ub294 \uc598\uae30\uc57c?")
B.aLc=s(["\uc624, \uc77d\uc5b4 \ubd24\uc5b4.","\uc88b\uc544, \uc774\ud574\ud588\uc5b4.","\ub124 \uc0dd\uac01\ub3c4 \uc54c\uaca0\uc5b4.","\uc774\ubc88\uc5d0\ub294 \ubc18\ubc15\ud558\uc9c0 \uc54a\uace0 \uc77d\uc5c8\uc5b4.","\uc6b0\ub9ac\ub07c\ub9b0 \uc228\uae38 \ud544\uc694 \uc5c6\uc796\uc544.","\ub124 \ub9d0\uc774\uba74 \ub05d\uae4c\uc9c0 \uc77d\uac8c \ub3fc."],t.s)
B.aIo=s(["\uc544\uc9c1 \uacb0\uacfc\ub3c4 \uc5c6\ub294\ub370 \ud655\uc2e0\ubd80\ud130 \ud558\uba74 \ub108\ubb34 \ube60\ub974\uc9c0.","\uc624\ub298 \uc7a5 \uc26c\uc796\uc544. \uadf8\ub7fc \ubc18\ub300\ub85c \ud2c0\ub9b4 \uc774\uc720\ub098 \ucc3e\uc544\ubcf4\uc790.","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\ub124. \uc2dc\uc7a5\uc774 \ub300\ub2f5\uc744 \ubbf8\ub8ec \uc148\uc774\uc9c0.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub124. \uc790, \ubc18\ub300\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0\ub3c4 \ubcf4\uc790.","\uc624\ub298\uc740 \ubc8c\uc5c8\ub294\ub370 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \ubc18\ub4f1\uc778\uc9c0 \uc7a0\uae50 \ud284 \uac74\uc9c0 \ubcf4\uc790.","\uc624\ub298\uc740 \uc783\uc5c8\uc9c0\ub9cc \uc9c0\uae08\uae4c\uc9c0 \ubc88 \uac74 \ub0a8\uc544 \uc788\ub124. \uadf8\ub0e5 \ud754\ub4e4\ub9b0 \uac74\uc9c0 \ubd10\uc57c\uc9c0.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \ub124 \uc0dd\uac01\uc774 \ud2c0\ub838\uc744 \uac00\ub2a5\uc131\ubd80\ud130 \ubcf4\uc790."],t.s)
B.aGX=s(["\ud2c0\ub838\ub2e4\uace0 \uce58\uc790. \uadf8\ub7fc \uc81c\uc77c \uba3c\uc800 \ubc84\ub9b4 \uc0dd\uac01\uc740 \ubb50\uc57c?","\uc190\ud574 \ub09c \uc774\uc720\uac00 \ub124 \uc124\uba85\uc774\ub791 \uc644\uc804\ud788 \ub2e4\ub978 \uac70\uba74?"],t.s)
B.aGb=s(["\ubc8c\uc5c8\ub2e4\uace0 \ub124 \uc0dd\uac01\uc774 \ub9de\uc740 \uac74\uac00? \uc6b4\uc774\uba74?","\uc798\ub410\ub124. \uadf8\ub7fc \ubc18\ub300\ub85c \uc5b8\uc81c\ubd80\ud130 \ud2c0\ub9b0 \uc598\uae30\uac00 \ub3fc?"],t.s)
B.aJt=s(["\ub0b4\uac00 \ubc18\ub300\ud574\ub3c4 \uc0b4 \uc774\uc720\uac00 \uc788\uc73c\uba74 \uadf8\ub54c \uc0dd\uac01\ud574 \ubd10.","\ub2e4\ub4e4 \uac19\uc740 \uc774\uc720\ub85c \uc0ac\ub294 \uac70\uba74, \uadf8 \uc774\uc720\uac00 \ud2c0\ub9b4 \ub54c\ub294?"],t.s)
B.aQV=s(["\ub124 \uc124\uba85\uc774 \ud2c0\ub838\ub2e4\uace0 \uac00\uc815\ud558\uba74 \ubb50\uac00 \ubcf4\uc5ec?","\uacb0\uacfc \ube7c\uace0\ub3c4 \uac19\uc740 \uc120\ud0dd\uc744 \ud588\uc744\uc9c0 \ub9d0\ud574 \ubd10."],t.s)
B.aKI=s([B.aGX,B.aGb,B.aJt,B.aQV],t.rj)
B.aKb=s(["\uc0ac\uacfc\ub294 \uc811\uc218.","\ub3c4\uc6c0\uc774 \ub410\ub2e4\ub2c8 \uc624\ub298 \ud1a0\ub860\uc740 \ubb34\uc2b9\ubd80\ub85c \ud574 \uc904\uac8c.","\uc7a0\uae50, \uc9c0\uae08\uc740 \ud1a0\ub860\ud560 \ub54c \uc544\ub2c8\ub124. \uadf8\ub0e5 \ub4e4\uc5b4 \uc904\uae4c?","\uc88b\uc544. \uc548 \ub418\uba74 \ubb58 \ud560\uc9c0\ub3c4 \ud558\ub098 \uc815\ud574 \ub450\uc790."],t.s)
B.aQ7=s(["\ubc18\ub300 \uc785\uc7a5\uc5d0\uc11c \ud55c \ubc88 \ub9d0\ud574 \ubcfc\ub798?","\ub124 \uc0dd\uac01\uc774 \ud2c0\ub838\ub2e4\uace0 \uc778\uc815\ud560 \ub54c\ub294 \uc5b8\uc81c\uc57c?","\ub0b4\uac00 \ubc18\ubc15\ud574\ub3c4 \ub05d\uae4c\uc9c0 \uc9c0\ud0ac \uc774\uc720\uac00 \uc788\uc5b4?"],t.s)
B.aGy=s(["\uc9c0\ub09c\ubc88\uc5d0\ub294 \u201c{memory}\u201d\ub77c\uace0 \ud588\uc9c0.","\ub0b4\uac00 \uae30\uc5b5\ud558\ub294 \uac74 \u201c{memory}\u201d\uc57c.","\uc804\uc5d0 \u201c{memory}\u201d\ub77c\uace0 \ub9d0\ud55c \ub370\uc11c \uc774\uc57c\uae30\uac00 \uc2dc\uc791\ub410\uc9c0."],t.s)
B.bJ7=new A.me(B.aLc,B.aIo,B.aKI,B.aKb,B.aQ7,B.aGy,"\uac19\uc740 \uc8fc\uc7a5\ub9cc \ubc18\ubcf5\ud558\uba74 \ud1a0\ub860\uc774 \uc544\ub2c8\uc9c0. \ubc18\ub300 \uc99d\uac70\ub294 \uc5c6\uc5b4?","\uc18d\ubcf4 \uc815\uc815. \uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \uc218\uc775\uc774\ub77c\uace0 \ubcf8 \uc774\uc720\uac00 \ubb50\uc57c?","\uc18d\ubcf4 \uc815\uc815. \uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \ub370\uc11c \uc783\uc740 \uac70\uc57c?","\uc18d\ubcf4 \uc815\uc815. \uc624\ub298\uc740 \uc190\ud574. \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8 \uc598\uae30\uc600\uc5b4?","\uc18d\ubcf4 \uc815\uc815. \uc624\ub298\uc740 \uc218\uc775. \uc804\uccb4\uac00 \uc544\uc9c1 \ub9c8\uc774\ub108\uc2a4\ub77c\ub294 \uc598\uae30\uc57c?")
B.aQJ=s(["\uc77d\uc5c8\uc5b4.","\ubb34\uc2a8 \ub73b\uc778\uc9c0 \uc54c\uaca0\uc5b4.","\ub124\uac00 \uc65c \uadf8\ub807\uac8c \ub9d0\ud588\ub294\uc9c0\ub3c4 \uc54c\uaca0\uc5b4.","\ub05d\uae4c\uc9c0 \uc77d\uace0 \uc0dd\uac01\ud574 \ubd24\uc5b4.","\ub124 \uc120\ud0dd\ub3c4 \uc774\uc81c\ub294 \ub098\ud55c\ud14c \uc911\uc694\ud574.","\ub9d0\ud558\uc9c0 \uc54a\uc740 \ubd80\ubd84\ub3c4 \uc870\uae08\uc740 \uc54c \uac83 \uac19\uc544."],t.s)
B.aG0=s(["\uc624\ub298 \uacb0\uacfc \uc544\uc9c1 \uc548 \ub098\uc654\uc5b4. \uc9c0\uae08\uc740 \ud310\ub2e8 \ubabb \ud574.","\uc624\ub298 \uc7a5 \uc26c\uc796\uc544. \uadf8\ub798\ub3c4 \uc9c0\ub09c \uae30\ub85d\uc740 \ubcfc \uc218 \uc788\uc5b4.","\uc624\ub298\uc740 \uac70\uc758 \uadf8\ub300\ub85c\uc57c. \ud558\ub8e8\ubcf4\ub2e4 \ud55c \ub2ec \ud750\ub984\uc744 \ubcf4\uc790.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\uc57c. \uc798\ub410\ub2e4\uace0 \uc774\uc720\ub97c \ub07c\uc6cc \ub9de\ucd94\uc9c4 \ub9c8.","\uc624\ub298\uc740 \ubc8c\uc5c8\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \ud750\ub984\uc774 \ubc14\ub00c\uc5c8\ub2e4\uace0 \ubcf4\uae34 \uc77c\ub7ec.","\uc624\ub298\uc740 \uc783\uc5c8\uc9c0\ub9cc \uc9c0\uae08\uae4c\uc9c0 \ubc88 \ub3c8\uc740 \ub0a8\uc544 \uc788\uc5b4. \uc774 \uc815\ub3c4\ub294 \uc0dd\uac01\ud588\ub358 \uac74\uc9c0 \ubd10.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \ucc98\uc74c \uc0dd\uac01\uacfc \uc0b0 \uae08\uc561\uc744 \ub458 \ub2e4 \ub2e4\uc2dc \ubd10."],t.s)
B.aMN=s(["\uc190\ud574 \ub09c \uc774\uc720\ubcf4\ub2e4 \ucc98\uc74c \uc0dd\uac01\uc774 \uc544\uc9c1 \ub9de\ub294\uc9c0\ubd80\ud130 \ubd10.","\uc9c0\uae08 \uc22b\uc790 \ub54c\ubb38\uc5d0 \ucc98\uc74c \uae30\uc900\uc744 \uc2ac\uca4d \ubc14\uafb8\uace0 \uc788\uc9c4 \uc54a\uc544?"],t.s)
B.aQz=s(["\ubc8c\uc5c8\uc5b4\ub3c4 \ucc98\uc74c \uc0dd\uac01\uc774 \ub9de\uc558\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\uc57c.","\uc798\ub41c \uacb0\uacfc\uc5d0 \ub9de\ucdb0 \uc774\uc720\ub97c \uc0c8\ub85c \ub9cc\ub4e4\uc9c4 \ub9c8."],t.s)
B.aNL=s(["\uc624\ub298 \uac00\uaca9 \ub9d0\uace0 \uc65c \ub2ec\ub77c\uc9c8 \ud68c\uc0ac\uc778\uc9c0\ubd80\ud130 \uc0dd\uac01\ud574.","\ud55c \ub2ec \ub4a4\uc5d0\ub3c4 \uac19\uc740 \uc774\uc720\ub85c \ub4e4\uace0 \uc788\uc744 \uc218 \uc788\ub294 \uac78 \uace8\ub77c."],t.s)
B.aLR=s(["\ucc98\uc74c \uc0dd\uac01\uc5d0\uc11c \ubc14\ub010 \uac8c \ubb54\uc9c0 \ud558\ub098\ub9cc \ucc3e\uc544.","\uadf8\ub54c \ubab0\ub790\ub358 \uc0ac\uc2e4\uc774 \uc9c0\uae08 \uc0dd\uae34 \uac74\uc9c0\ubd80\ud130 \ubcf4\uc790."],t.s)
B.aI4=s([B.aMN,B.aQz,B.aNL,B.aLR],t.rj)
B.aLs=s(["\uc65c \uadf8\ub7ac\ub294\uc9c0\ub294 \uc54c\uaca0\uc5b4.","\ub3c4\uc6c0\uc774 \ub410\ub2e4\uba74 \uadf8\uac78\ub85c \ucda9\ubd84\ud574.","\ubb50\uac00 \ubd88\uc548\ud55c\uc9c0 \ub098\ub220 \ubcf4\uba74 \uc6b0\ub9ac\uac00 \ubc14\uafc0 \uc218 \uc788\ub294 \uac8c \ubcf4\uc5ec.","\uc88b\uc544. \uadf8\ub2e4\uc74c\uc5d0 \ubb58 \ud560\uc9c0\ub3c4 \uac19\uc774 \uc0dd\uac01\ud574 \ubcf4\uc790."],t.s)
